(function(){
  var panel=[];
  document.querySelectorAll("[class*=vote],[class*=view],[class*=read],[class*=count],[class*=comment]").forEach(function(e){var x=(e.textContent||"").trim().split(String.fromCharCode(10)).join(" ");if(x&&x.length<20)panel.push(x)});
  var uniq=panel.filter(function(v,i){return panel.indexOf(v)===i});
  return JSON.stringify(uniq.slice(0,10));
})()
